content.content:
1	/* ============================================
2	   共通リセット
3	   ============================================ */
4	html { scroll-behavior: smooth; }
5	@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { animation: none !important; } }
6	* { box-sizing: border-box; }
7	body { margin: 0; font-family: "Zen Kaku Gothic New", "Archivo", system-ui, sans-serif; -webkit-font-smoothing: antialiased; }
8	a { color: inherit; text-decoration: none; }
9	
10	/* ページテーマ（body class="page-xxx"） */
11	/* page-portfolio（404）・page-privacy はTOPページと同じネイビー×オレンジ配色。page-pianist・page-horror は現行デザインを維持（別途リニューアル予定のため変更しない） */
12	body.page-portfolio { background: #FFFFFF; color: #172E4A; }
13	body.page-privacy { background: #FFFFFF; color: #172E4A; }
14	body.page-pianist { background: #08080A; color: #F2EFE9; }
15	body:has(.pn-shell) {
16	  color: #F2EFE9;
17	  background: linear-gradient(180deg,rgba(8,8,10,0.4),rgba(8,8,10,0.65)), url("images/25253200_l.webp") center / cover no-repeat fixed, #08080A;
18	}
19	body:has(.top-shell) {
20	  background: #FFFFFF;
21	}
22	body.page-portfolio a:hover { color: #DC8541; }
23	body.page-privacy a:hover { color: #DC8541; }
24	body.page-pianist a:hover { color: #E4C97E; }
25	.pn-shell a:hover { color: #E4C97E; }
26	body.page-portfolio ::selection,
27	body.page-privacy ::selection { background: #F6D3B0; color: #172E4A; }
28	
29	body.page-horror { background: #07070A; color: #D6D2CB; }
30	body.page-horror a:hover { color: #9B2C22; }
31	
32	/* ============================================
33	   キーフレームアニメーション
34	   ============================================ */
35	@keyframes fadeup { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
36	@keyframes flick { 0%,100% { opacity: .85; } 47% { opacity: .85; } 48% { opacity: .35; } 52% { opacity: .9; } 70% { opacity: .6; } }
37	
38	/* ============================================
39	   共通ユーティリティ
40	   ============================================ */
41	.container { max-width: 1180px; margin: 0 auto; padding-inline: clamp(20px,5vw,64px); }
42	
43	.tag-row { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 10px; }
44	.tag { display: inline-flex; align-items: center; font-size: 12px; letter-spacing: 0.01em; color: #3E4A5C; border: 2.5px solid #172E4A; border-radius: 999px; padding: 8px 16px; background: #FFFFFF; white-space: nowrap; }
45	.tag--onDark { color: #EAF0F6; border-color: rgba(234,240,246,0.32); background: rgba(255,255,255,0.06); }
46	
47	.btn-group { display: flex; flex-wrap: wrap; gap: 14px; align-items: center; }
48	.btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; font-weight: 700; font-size: 14px; letter-spacing: 0.09em; padding: 20px 34px; border-radius: 999px; border: 3px solid transparent; cursor: pointer; transition: background .25s ease, border-color .25s ease, color .25s ease, transform .15s ease; white-space: nowrap; }
49	.btn:hover { transform: translateY(-1px); }
50	.btn--primary { background: #DC8541; color: #FFFFFF; box-shadow: 5px 5px 0 #172E4A; }
51	.btn--primary:hover { background: #C06E2E; }
52	.btn--secondary { background: #FFFFFF; color: #172E4A; border-color: #172E4A; }
53	.btn--secondary:hover { background: #172E4A; color: #FFFFFF; }
54	.btn--onDark { background: transparent; color: #FFFFFF; border-color: rgba(255,255,255,0.5); }
55	.btn--onDark:hover { background: rgba(255,255,255,0.12); border-color: #FFFFFF; }
56	.btn--sm { padding: 13px clamp(14px,1.6vw,22px); font-size: 12px; font-weight: 600; box-shadow: 4px 4px 0 #172E4A; }
57	
58	/* ============================================
59	   shell（各ページ共通の外枠カード／pianist・horror・privacyと共有のため触らない）
60	   ============================================ */
61	.shell {
62	  container-type: inline-size;
63	  max-width: 375px;
64	  margin: 0 auto;
65	  min-height: 100svh;
66	  position: relative;
67	  overflow-x: hidden;
68	  display: flex;
69	  flex-direction: column;
70	  background: #F5F8FC;
71	  box-shadow: 0 0 80px rgba(18,36,63,0.16);
72	}
73	.shell--muted { background: #F0F5FA; }
74	.shell--dark { background: #0B0B0C; box-shadow: 0 0 80px rgba(0,0,0,0.5); }
75	
76	.skip-link { position: absolute; left: -9999px; top: 0; background: #12243F; color: #F5F8FC; padding: 12px 18px; z-index: 200; }
77	.skip-link:focus { left: 12px; top: 12px; }
78	
79	/* ============================================
80	   page-header（下層ページの戻るリンクヘッダー／pianist・horror・privacyと共有のため触らない）
81	   ============================================ */
82	.page-header { padding: 24px clamp(20px,6cqw,80px); display: flex; justify-content: space-between; align-items: center; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.16em; }
83	.page-header--dark { color: #8A8580; }
84	.page-header__back { display: inline-flex; align-items: center; gap: 10px; transition: gap .3s ease; }
85	.page-header__back:hover { gap: 18px; }
86	.page-header__label { color: #7B8DA6; }
87	
88	/* ============================================
89	   page-footer（下層ページ共通フッター／pianist・horror・privacyと共有のため触らない）
90	   ============================================ */
91	.page-footer { padding: clamp(40px,5cqw,72px) clamp(20px,6cqw,80px); border-top: 1px solid #D3DEEB; display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #7B8DA6; margin-top: auto; }
92	.page-footer--dark { border-top-color: #1E1D1D; color: #5A5652; }
93	
94	/* privacy は新デザイン（ネイビー×オレンジ）に上書き（pianist・horrorの共有.shell/.page-header/.page-footerには影響させない） */
95	body.page-privacy .shell {
96	  background: #FFFFFF;
97	  box-shadow: 0 0 90px rgba(23,46,74,0.10);
98	}
99	body.page-privacy .page-header,
100	body.page-privacy .page-footer {
101	  font-family: Jost, sans-serif;
102	}
103	body.page-privacy .page-header__label,
104	body.page-privacy .page-footer {
105	  color: #7C8798;
106	}
107	body.page-privacy .page-footer {
108	  border-top-color: #E3E6EB;
109	}
110	
111	/* ============================================
112	   top-shell（TOPページのラッパー／固定フレームは使わずフル幅レスポンシブ／
113	   「手描きポップ」デザイン：太め枠線・オフセット影・回転バッジが基調）
114	   ============================================ */
115	.top-shell {
116	  min-height: 100svh;
117	  display: flex;
118	  flex-direction: column;
119	  overflow-x: hidden;
120	}
121	body:has(.top-shell) a:hover { color: #DC8541; }
122	body:has(.top-shell) ::selection { background: #F6D3B0; color: #172E4A; }
123	
124	@keyframes prupru {
125	  0% { transform: rotate(-2deg) translate(0,0); }
126	  12% { transform: rotate(2.4deg) translate(2px,-1px); }
127	  26% { transform: rotate(-3.2deg) translate(-2px,1px); }
128	  40% { transform: rotate(2.6deg) translate(2px,1px); }
129	  54% { transform: rotate(-2.4deg) translate(-1px,-1px); }
130	  68% { transform: rotate(1.6deg) translate(1px,0); }
131	  84% { transform: rotate(-2.4deg) translate(-1px,0); }
132	  100% { transform: rotate(-2deg) translate(0,0); }
133	}
134	
135	/* ============================================
136	   site-header（TOPページ固定ヘッダー／DCコンポーネントの状態クラス hero-nav / menu は名称を維持）
137	   ============================================ */
138	.hero-nav {
139	  position: sticky; top: 0; z-index: 96;
140	  display: flex; align-items: center; justify-content: space-between;
141	  gap: 20px;
142	  padding: 16px clamp(18px,5vw,56px);
143	  background: rgba(255,255,255,0.93);
144	  border-bottom: 4px solid #172E4A;
145	  backdrop-filter: blur(10px);
146	  -webkit-backdrop-filter: blur(10px);
147	}
148	.hero-nav__h1 { margin: 0; }
149	.hero-nav__logo { display: inline-flex; align-items: baseline; gap: 12px; line-height: 1; transition: opacity .2s ease; }
150	.hero-nav__logo-main { font-size: 18px; letter-spacing: 0.09em; color: #172E4A; font-weight: 500; transition: color .2s ease; }
151	.hero-nav__logo-sub { font-size: 9px; letter-spacing: 0.26em; color: #DC8541; transition: color .2s ease; }
152	.hero-nav__logo:hover .hero-nav__logo-main { color: #DC8541; }
153	.hero-nav__logo:hover .hero-nav__logo-sub { color: #172E4A; }
154	
155	.hero-nav__nav { display: none; }
156	.hero-nav__nav-list { list-style: none; margin: 0; padding: 0; display: flex; align-items: center; gap: clamp(14px,1.8vw,28px); font-size: 13.5px; color: #3E4A5C; }
157	.hero-nav__nav-list a { transition: color .2s ease; }
158	.hero-nav__nav-list a:hover { color: #DC8541; }
159	.hero-nav__actions { display: flex; align-items: center; gap: 10px; }
160	.hero-nav__cta--compact { display: none; }
161	
162	.hero-nav__toggle {
163	  width: 44px; height: 44px; display: flex; flex-direction: column;
164	  justify-content: center; align-items: center; gap: 6px; background: none; border: none;
165	  cursor: pointer; padding: 0; flex: none;
166	}
167	.hero-nav__bar {
168	  display: block; height: 2px; width: 22px; border-radius: 2px; background: #172E4A;
169	  transition: transform .35s cubic-bezier(.2,.7,.2,1), opacity .2s ease;
170	}
171	.hero-nav.is-open .hero-nav__bar--top { transform: translateY(4px) rotate(45deg); }
172	.hero-nav.is-open .hero-nav__bar--bottom { transform: translateY(-4px) rotate(-45deg); }
173	
174	@media (min-width: 880px) {
175	  .hero-nav__nav { display: block; }
176	  .hero-nav__toggle { display: none; }
177	  .hero-nav__cta--compact { display: none; }
178	}
179	@media (max-width: 879px) {
180	  .hero-nav__cta--full { display: none; }
181	  .hero-nav__cta--compact { display: inline-flex; }
182	}
183	
184	/* ============================================
185	   menu（ハンバーガーで開くフルスクリーンナビ／DCコンポーネントの状態クラス menu は名称を維持）
186	   ============================================ */
187	.menu {
188	  position: fixed; inset: 0; z-index: 95;
189	  background: #172E4A;
190	  display: flex; flex-direction: column;
191	  overflow-y: auto; -webkit-overflow-scrolling: touch;
192	  padding: 96px clamp(24px,7vw,56px) 48px;
193	  transition: opacity .4s ease, visibility .4s ease;
194	  opacity: 0; visibility: hidden; pointer-events: none;
195	}
196	.menu.is-open { opacity: 1; visibility: visible; pointer-events: auto; }
197	.menu__cta { margin-bottom: clamp(30px,6vw,48px); }
198	.menu__inner { display: grid; gap: clamp(28px,6vw,44px); width: 100%; max-width: 420px; }
199	.menu__group-title { font-size: 11px; letter-spacing: 0.24em; color: #9DB4CD; margin: 0 0 16px; }
200	.menu__nav-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; font-weight: 700; font-size: 20px; line-height: 1.25; color: #FFFFFF; }
201	.menu__social-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; font-size: 14px; color: #FFFFFF; }
202	.menu__social-link { display: inline-flex; align-items: center; gap: 12px; transition: transform .3s ease; }
203	.menu__social-link:hover { transform: translateX(8px); color: #DC8541; }
204	.menu__personal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 16px; }
205	.menu__personal-link { display: block; }
206	.menu__personal-link-title { display: block; font-size: 15px; color: #FFFFFF; transition: transform .3s ease; }
207	.menu__personal-link:hover .menu__personal-link-title { transform: translateX(8px); color: #DC8541; }
208	.menu__personal-link-desc { display: block; font-size: 12px; color: #9DB4CD; margin-top: 4px; }
209	.menu__credit { margin: 36px 0 0; font-size: 11px; letter-spacing: 0.16em; color: #6B85A6; }
210	
211	@media (min-width: 880px) {
212	  .menu { display: none; }
213	}
214	
215	/* ============================================
216	   section 基本パターン
217	   ============================================ */
218	.section { position: relative; padding-block: clamp(66px,9vw,120px); background: #FFFFFF; overflow: hidden; }
219	.section--alt { background: #FFF3E6; }
220	.section--dark { background: #172E4A; color: #EAF0F6; }
221	.section--tight { padding-block: clamp(40px,6vw,80px); }
222	
223	.section__head-row { display: flex; flex-wrap: wrap; align-items: center; gap: clamp(22px,4vw,48px); margin-bottom: clamp(34px,5vw,56px); }
224	.section__head { flex: 1 1 320px; min-width: 0; max-width: 760px; margin-bottom: clamp(32px,5vw,64px); }
225	.section__head-row .section__head { margin-bottom: 0; }
226	.section__head--center { margin-inline: auto; text-align: center; }
227	.section__deco { flex: 0 0 auto; width: clamp(120px,17vw,200px); aspect-ratio: 1/1; }
228	.section__deco img { width: 100%; height: 100%; object-fit: cover; display: block; border-radius: 32px; }
229	.section__eyebrow {
230	  display: inline-block; margin: 0 0 18px; font-weight: 700; font-size: 11px; line-height: 1;
231	  letter-spacing: 0.22em; color: #FFFFFF; background: #172E4A; padding: 9px 16px; border-radius: 999px;
232	  transform: rotate(-2deg);
233	}
234	.section--dark .section__eyebrow, .section--cta .section__eyebrow { background: #DC8541; color: #172E4A; }
235	.section__heading { margin: 0; font-weight: 900; font-size: clamp(26px,3.6vw,44px); line-height: 1.42; letter-spacing: -0.01em; color: #172E4A; }
236	.section--dark .section__heading, .section--cta .section__heading { color: #FFFFFF; }
237	.section__lead { margin: 18px 0 0; font-size: 15px; line-height: 2; color: #56637A; }
238	.section--dark .section__lead { color: #C3D0E0; }
239	
240	/* ============================================
241	   hero
242	   ============================================ */
243	.hero { padding-top: clamp(48px,8vw,92px); padding-bottom: clamp(60px,9vw,104px); background: linear-gradient(180deg,#FFFFFF 0%,#FFF3E6 100%); overflow: hidden; }
244	.hero__inner { display: grid; gap: clamp(40px,6vw,64px); align-items: center; }
245	.hero__eyebrow { display: flex; align-items: center; gap: 14px; font-size: 11.5px; letter-spacing: 0.22em; color: #8A7B6C; margin: 0 0 clamp(20px,3vw,26px); }
246	.hero__eyebrow-line { width: 7px; height: 7px; border-radius: 50%; background: #DC8541; }
247	.hero__heading { margin: 0; font-weight: 900; font-size: clamp(26px,4.2vw,52px); line-height: 1.45; letter-spacing: -0.01em; color: #172E4A; }
248	.hero__line { display: block; }
249	.hero__highlight { position: relative; display: inline-block; color: #172E4A; }
250	.hero__highlight::after { content: ""; position: absolute; left: 0; right: 0; bottom: 6px; height: 12px; background: rgba(220,133,65,0.24); border-radius: 6px; z-index: -1; }
251	.hero__lead { margin: clamp(24px,3vw,32px) 0 0; font-size: 15px; line-height: 2.05; color: #56637A; max-width: 46ch; }
252	.hero__tags { margin-top: clamp(22px,3vw,30px); }
253	.hero__actions { margin-top: clamp(28px,4vw,38px); }
254	
255	.hero__visual { position: relative; display: flex; justify-content: center; }
256	.hero__photo {
257	  position: relative; width: 100%; max-width: 320px; margin: 0 auto; aspect-ratio: 4/5;
258	  border: 2.5px solid #172E4A; border-radius: 170px 170px 26px 26px;
259	  background-image: repeating-linear-gradient(135deg,#FFE0BF 0 12px,#FFF3E6 12px 24px);
260	  display: flex; align-items: center; justify-content: center; overflow: hidden;
261	}
262	.hero__photo-label { font-family: ui-monospace,Menlo,monospace; font-size: 11px; letter-spacing: 0.16em; color: #8A93A3; background: #FFFFFF; padding: 6px 14px; border: 1px solid #E3E6EB; border-radius: 999px; }
263	
264	@media (min-width: 860px) {
265	  .hero__inner { grid-template-columns: minmax(0,1fr) 320px; }
266	  .hero__visual { order: 2; }
267	}
268	
269	/* ============================================
270	   tile-grid（PROBLEMS / TEAM / WORK STYLE 共通／太枠＋オフセット影のポップカード）
271	   ============================================ */
272	.tile-grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2,1fr); gap: 16px; }
273	.tile { display: flex; flex-direction: column; align-items: center; gap: 18px; text-align: center; background: #FFFFFF; border: 3px solid #172E4A; border-radius: 24px; padding: clamp(24px,3vw,32px); box-shadow: 6px 6px 0 #172E4A; }
274	.tile__icon img { width: auto; height: clamp(60px,8vw,92px); object-fit: contain; display: block; }
275	.tile__text { margin: 0; font-size: 14.5px; line-height: 1.85; color: #172E4A; font-weight: 500; }
276	.tile__label { font-size: 14px; font-weight: 700; line-height: 1.6; color: #172E4A; }
277	
278	.tile-grid--dot .tile--row { flex-direction: row; align-items: center; justify-content: flex-start; gap: 14px; text-align: left; box-shadow: none; padding: 20px 22px; }
279	.tile__dot { flex: none; width: 28px; height: 28px; border-radius: 50%; background: rgba(220,133,65,0.14); display: flex; align-items: center; justify-content: center; }
280	.tile__dot::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: #DC8541; }
281	
282	@media (min-width: 640px) {
283	  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
284	}
285	@media (min-width: 880px) {
286	  .tile-grid--6 { grid-template-columns: repeat(6,1fr); }
287	  .tile-grid--3 { grid-template-columns: repeat(3,1fr); }
288	}
289	
290	/* ============================================
291	   timeline（SCOPE / PROFILE経歴 共通／カード積み上げ型のチェックリスト）
292	   ============================================ */
293	.timeline { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
294	.timeline__item { display: flex; align-items: center; flex-wrap: wrap; gap: 6px 16px; padding: 16px 20px; border: 3px dashed #172E4A; border-radius: 18px; background: #FFFFFF; }
295	.timeline__no { font-size: 12px; letter-spacing: 0.14em; color: #A7AFBC; flex: none; width: 22px; }
296	.timeline__label { flex: 1; font-size: 15px; font-weight: 500; color: #172E4A; min-width: 120px; }
297	.timeline__badge { flex: none; font-size: 11px; letter-spacing: 0.04em; color: #8A93A3; }
298	.timeline__item--covered { border: 3px solid #172E4A; border-left-width: 10px; border-left-color: #DC8541; }
299	.timeline__item--covered .timeline__no { color: #DC8541; }
300	.timeline__item--covered .timeline__badge { color: #C06E2E; font-weight: 600; background: rgba(220,133,65,0.12); border-radius: 999px; padding: 6px 12px; }
301	.timeline__item--highlight { border: 3px solid #172E4A; background: #A85A1E; }
302	.timeline__item--highlight .timeline__no,
303	.timeline__item--highlight .timeline__label,
304	.timeline__item--highlight .timeline__badge { color: #FFFFFF; }
305	
306	.timeline--profile .timeline__item { border: 3px solid #172E4A; border-style: solid; display: flex; align-items: flex-start; gap: 18px; text-align: left; }
307	.timeline--profile .timeline__label { flex: none; width: 78px; font-size: 13px; font-weight: 600; color: #172E4A; }
308	.timeline--profile .timeline__badge { flex: 1; min-width: 180px; font-size: 13.5px; line-height: 1.9; letter-spacing: normal; color: #56637A; font-weight: 400; text-align: left; }
309	.timeline--profile .timeline__item--highlight { background: #A85A1E; }
310	.timeline--profile .timeline__item--highlight .timeline__label,
311	.timeline--profile .timeline__item--highlight .timeline__badge { color: #FFFFFF; }
312	
313	/* ============================================
314	   philosophy（PHILOSOPHY）
315	   ============================================ */
316	.chain { display: flex; flex-direction: column; gap: 14px; align-items: stretch; max-width: 920px; margin: 0 auto; }
317	.chain__node { flex: 1; min-width: 0; background: #1E3A5C; color: #FFFFFF; border: 3px solid #E0B98F; border-radius: 22px; padding: clamp(22px,3vw,30px); text-align: center; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; }
318	.chain__node--accent { background: #FFFFFF; color: #172E4A; border: none; box-shadow: 8px 8px 0 #A85A1E; }
319	.chain__icon img { width: clamp(60px,8vw,92px); height: clamp(60px,8vw,92px); object-fit: contain; display: block; }
320	.chain__role { margin: 0; font-weight: 600; font-size: 13px; letter-spacing: 0.1em; color: inherit; }
321	.chain__node--accent .chain__role { color: #C06E2E; }
322	.chain__points { list-style: none; margin: 16px 0 0; padding: 0; display: flex; flex-wrap: wrap; justify-content: center; gap: 8px; }
323	.chain__points .tag { font-size: 11px; padding: 6px 13px; border: 2.5px solid #172E4A; }
324	.chain__arrow { display: none; }
325	
326	.philosophy__points { list-style: none; margin: 22px 0 0; padding: 0; display: grid; gap: 12px; max-width: 40ch; }
327	.philosophy__points li { font-size: 14.5px; color: #FFFFFF; padding-left: 22px; position: relative; }
