543	.dream-stage__insects { position: absolute; inset: 24px; color: #B9B0A9; opacity: 0; font: 24px/1 ui-monospace, monospace; }
544	.dream-stage__insects i { position: absolute; font-style: normal; }
545	.dream-stage__insects i:nth-child(1) { left: 14%; top: 18%; }.dream-stage__insects i:nth-child(2) { left: 76%; top: 20%; }.dream-stage__insects i:nth-child(3) { left: 21%; top: 70%; }.dream-stage__insects i:nth-child(4) { left: 68%; top: 74%; }.dream-stage__insects i:nth-child(5) { left: 44%; top: 10%; }.dream-stage__insects i:nth-child(6) { left: 85%; top: 51%; }.dream-stage__insects i:nth-child(7) { left: 6%; top: 48%; }.dream-stage__insects i:nth-child(8) { left: 48%; top: 86%; }
546	.dream-stage--still .dream-stage__ear { opacity: .08; transform: rotate(-17deg) scale(.82); }
547	.dream-stage--sound .dream-stage__ear-pulse { animation-duration: .38s; }
548	.dream-stage--nothing .dream-stage__ear { opacity: .04; transform: translateX(64px) rotate(-17deg); }
549	.dream-stage--nothing .dream-stage__caption { animation: flick 1.2s infinite; }
550	.dream-stage--inside .dream-stage__ear { transform: rotate(-17deg) scale(1.08); }
551	.dream-stage--inside .dream-stage__ear-hole { box-shadow: 0 0 22px 8px rgba(155,44,34,.36); }
552	.dream-stage--pull .dream-stage__ear { animation: earShake .16s ease-in-out infinite alternate; }
553	.dream-stage--pull .dream-stage__ear-pulse { animation-duration: .18s; }
554	.dream-stage--release .dream-stage__ear { opacity: .2; transform: rotate(-17deg) scale(.7); }
555	.dream-stage--release .dream-stage__insects { opacity: .8; animation: insectBurst 1.1s ease-out both; }
556	.dream-stage__caption { position: relative; margin: 0; color: #D6D2CB; font: 11px Archivo, sans-serif; letter-spacing: .22em; text-align: center; animation: flick 4s infinite; }
557	.dream-experience__copy { white-space: pre-line; min-height: 92px; margin: 28px 0 0; color: #B9B0A9; font-size: 14px; line-height: 2.1; }
558	.dream-experience__action { margin-top: 22px; border: 1px solid #4A2724; background: transparent; color: #D6D2CB; padding: 15px 18px; cursor: pointer; font: 11px Archivo, sans-serif; letter-spacing: .18em; transition: background .3s ease, border-color .3s ease; }
559	.dream-experience__action:hover { background: #9B2C22; border-color: #9B2C22; }
560	.dream-experience__progress { margin: 18px 0 0; color: #5A5652; font: 10px Archivo, sans-serif; letter-spacing: .2em; }
561	@keyframes dreamDrift { from { transform: translateX(0); } to { transform: translateX(48px); } }
562	@keyframes earPulse { 0%,100% { transform: scale(.8); opacity: .15; } 50% { transform: scale(1.2); opacity: .8; } }
563	@keyframes earShake { from { transform: rotate(-19deg) translateX(-4px); } to { transform: rotate(-14deg) translateX(4px); } }
564	@keyframes insectBurst { from { transform: scale(.2); opacity: 0; } 35% { opacity: .9; } to { transform: scale(1.25); opacity: .72; } }
565	@media (prefers-reduced-motion: reduce) { .dream-stage__sky, .dream-stage__ear-pulse { animation: none; } }
566	
567	/* ============================================
568	   policy（PRIVACYページ）
569	   ============================================ */
570	.policy { max-width: 720px; margin: 0 auto; padding: clamp(40px,8vw,90px) clamp(20px,6vw,40px) clamp(60px,8vw,100px); }
571	.policy__eyebrow { margin: 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #DC8541; }
572	.policy__title { margin: 18px 0 0; font-weight: 500; font-size: clamp(24px,4vw,38px); line-height: 1.5; letter-spacing: -0.01em; color: #172E4A; }
573	.policy__intro { margin: 22px 0 0; font-size: 14px; line-height: 2.1; color: #56637A; }
574	.policy__note { font-family: Jost, sans-serif; font-size: 12px; letter-spacing: 0.08em; color: #A7AFBC; }
575	.policy-list { list-style: none; margin: clamp(36px,5vw,56px) 0 0; padding: 0; display: grid; gap: clamp(28px,4vw,44px); }
576	.policy-list__item { border-top: 1px solid #E3E6EB; padding-top: 22px; }
577	.policy-list__no { margin: 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.16em; color: #A7AFBC; }
578	.policy-list__heading { margin: 10px 0 0; font-weight: 500; font-size: 17px; color: #172E4A; }
579	.policy-list__body { margin: 12px 0 0; font-size: 14px; line-height: 2.1; color: #56637A; }
580	.policy__updated { margin: clamp(36px,5vw,56px) 0 0; font-family: Jost, sans-serif; font-size: 11px; letter-spacing: 0.14em; color: #A7AFBC; }
581	.policy__cta { margin-top: clamp(28px,4vw,40px); display: inline-flex; align-items: center; gap: 12px; background: #DC8541; color: #FFFFFF; font-weight: 600; font-family: Jost, sans-serif; font-size: 13px; letter-spacing: 0.1em; padding: 17px 30px; border-radius: 999px; transition: background .25s ease; }
582	.policy__cta:hover { background: #C06E2E; }
583	
584	/* ============================================
585	   error-page（404.html / support.js非依存の静的ページ）
586	   ============================================ */
587	.error-page { max-width: 480px; margin: 0 auto; min-height: 100svh; display: flex; flex-direction: column; align-items: flex-start; justify-content: center; gap: 18px; padding: clamp(32px,8vw,64px); }
588	.error-page__code { margin: 0; font-family: Jost, sans-serif; font-weight: 400; font-size: clamp(56px,14vw,100px); line-height: 1; color: #172E4A; }
589	.error-page__title { margin: 0; font-size: 18px; font-weight: 500; color: #172E4A; }
590	.error-page__message { margin: 0; font-size: 14px; line-height: 2; color: #56637A; }
591	.error-page__back { margin-top: 10px; display: inline-flex; align-items: center; gap: 12px; background: #DC8541; color: #FFFFFF; font-weight: 600; font-family: Jost, sans-serif; font-size: 13px; letter-spacing: 0.1em; padding: 17px 30px; border-radius: 999px; transition: background .25s ease; }
592	.error-page__back:hover { background: #C06E2E; }
593	
594	
595	/* ============================================
596	   PIANIST v2（黒×ゴールド）
597	   ここから下が pianist.html 専用のスタイルです
598	   ============================================ */
599	.pn-shell ::selection { background: #C9A34E; color: #08080A; }
600	.pn-shell { background: #08080A; box-shadow: 0 0 90px rgba(0,0,0,0.65); }
601	.pn-shell .page-header { color: #8A8579; position: relative; z-index: 10; }
602	.pn-shell .page-header__label { color: #6E6A61; }
603	.pn-shell .page-footer { border-top-color: #23211D; color: #6E6A61; position: relative; z-index: 10; }
604	
605	/* --- 音符レイヤー（スクロールに合わせて弧を描いて流れる装飾） --- */
606	.pn-notes { position: fixed; top: 0; bottom: 0; left: 50%; transform: translateX(-50%); width: min(100%,375px); z-index: 1; pointer-events: none; overflow: hidden; }
607	.pn-wave { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
608	.pn-wave__ghost { fill: none; stroke: rgba(201,163,78,0.15); stroke-width: 1; }
609	.pn-wave__live { fill: none; stroke: url(#pnWaveGrad); stroke-width: 1.4; stroke-linecap: round; }
610	.pn-note { position: absolute; left: 0; top: 0; font-family: "Cormorant Garamond", Georgia, serif; line-height: 1; color: rgba(201,163,78,0.55); will-change: transform; }
611	.pn-note__glyph { display: block; transform-origin: 50% 50%; animation: pnDrift var(--pn-dur,7s) ease-in-out infinite; }
612	.pn-note--lead { font-size: 26px; color: #C9A34E; --pn-dur: 6.5s; }
613	.pn-note--trail-a { font-size: 16px; color: rgba(201,163,78,0.5); --pn-dur: 8.5s; }
614	.pn-note--trail-b { font-size: 12px; color: rgba(201,163,78,0.3); --pn-dur: 10s; }
615	@keyframes pnDrift { 0%,100% { transform: translateY(0) rotate(0deg); } 50% { transform: translateY(-6px) rotate(-5deg); } }
616	@media (prefers-reduced-motion: reduce) { .pn-note__glyph { animation: none; } }
617	
618	/* --- 共通パーツ --- */
619	.pn-wrap { position: relative; z-index: 10; }
620	.pn-section { padding: clamp(56px,9cqw,120px) clamp(22px,6cqw,80px); }
621	.pn-section--line { border-top: 1px solid #23211D; }
622	.pn-eyebrow { margin: 0 0 clamp(22px,3cqw,36px); font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.34em; color: #C9A34E; }
623	.pn-h2 { margin: 0 0 clamp(28px,4cqw,44px); font-family: "Cormorant Garamond", Georgia, serif; font-weight: 400; font-size: clamp(28px,6cqw,44px); line-height: 1.3; letter-spacing: 0.02em; color: #F2EFE9; }
624	.pn-h2 .pn-h2__ja { display: block; margin-top: 10px; font-family: "Zen Old Mincho", serif; font-size: 13px; letter-spacing: 0.22em; color: #8A8579; }
625	.pn-text { margin: 0; font-family: "Zen Old Mincho", serif; font-size: 14px; line-height: 2.3; color: #C6C1B7; }
626	.pn-stack { display: grid; gap: 22px; }
627	.pn-rule { height: 1px; background: linear-gradient(90deg,rgba(201,163,78,0.55),rgba(201,163,78,0)); }
628	
629	/* --- 写真プレースホルダー --- */
630	.pn-photo { position: relative; aspect-ratio: 4/5; border: 1px solid #23211D; background-image: repeating-linear-gradient(135deg,#0E0E10 0 10px,#121214 10px 20px); display: flex; align-items: center; justify-content: center; overflow: hidden; }
631	.pn-photo--wide { aspect-ratio: 16/10; }
632	.pn-photo__img { display: block; width: 100%; height: 100%; object-fit: cover; }
633	.pn-photo__label { font-family: ui-monospace,Menlo,monospace; font-size: 10px; letter-spacing: 0.16em; color: #6E6A61; border: 1px solid #23211D; background: #08080A; padding: 6px 12px; }
634	
635	/* --- 演奏会セクション（普段は非表示） --- */
636	.pn-concert { position: relative; z-index: 10; padding: clamp(30px,6cqw,54px) clamp(22px,6cqw,80px) clamp(34px,6cqw,58px); border-bottom: 1px solid rgba(201,163,78,0.28); }
637	.pn-concert__badge { display: inline-flex; align-items: center; gap: 10px; font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.28em; color: #C9A34E; border: 1px solid rgba(201,163,78,0.42); padding: 8px 14px; }
638	.pn-concert__title { margin: 22px 0 0; font-family: "Zen Old Mincho", serif; font-weight: 500; font-size: clamp(20px,4.6cqw,30px); line-height: 1.6; color: #F2EFE9; }
639	.pn-concert__date { margin: 18px 0 0; font-family: "Cormorant Garamond", Georgia, serif; font-size: clamp(26px,6cqw,40px); line-height: 1.2; color: #E4C97E; letter-spacing: 0.02em; }
640	.pn-concert__meta { list-style: none; margin: 20px 0 0; padding: 0; display: grid; gap: 12px; }
641	.pn-concert__meta li { display: grid; grid-template-columns: 68px 1fr; gap: 12px; font-size: 13px; line-height: 1.9; color: #C6C1B7; font-family: "Zen Old Mincho", serif; }
642	.pn-concert__meta span { font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.2em; color: #6E6A61; padding-top: 4px; }
643	.pn-concert__link { margin-top: 26px; display: inline-flex; align-items: center; gap: 14px; font-family: Archivo, sans-serif; font-size: 11px; letter-spacing: 0.24em; color: #08080A; background: linear-gradient(120deg,#C9A34E,#E4C97E); padding: 16px 26px; transition: gap .3s ease; }
644	.pn-concert__link:hover { gap: 24px; color: #08080A; }
645	
646	/* --- HERO --- */
647	.pn-hero { padding: clamp(40px,8cqw,90px) clamp(22px,6cqw,80px) clamp(56px,9cqw,110px); }
648	.pn-hero__title { margin: 0; font-family: "Cormorant Garamond", Georgia, serif; font-weight: 300; font-size: clamp(56px,17cqw,190px); line-height: 0.95; letter-spacing: 0.04em; color: #F2EFE9; }
649	.pn-hero__sub { margin: 18px 0 0; font-family: "Cormorant Garamond", Georgia, serif; font-style: italic; font-size: clamp(17px,3.6cqw,26px); color: #C9A34E; letter-spacing: 0.04em; }
650	.pn-hero__name { margin: 30px 0 0; font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.34em; color: #6E6A61; }
651	.pn-hero__photo { margin-top: clamp(34px,6cqw,64px); }
652	.pn-hero__lead { margin-top: clamp(32px,5cqw,56px); }
653	
654	/* --- PROFILE --- */
655	.pn-profile__aside { margin-top: clamp(34px,5cqw,56px); border-top: 1px solid #23211D; padding-top: 26px; display: grid; gap: 22px; }
656	.pn-profile__label { margin: 0 0 8px; font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.26em; color: #C9A34E; }
657	.pn-profile__item { margin: 0; font-family: "Zen Old Mincho", serif; font-size: 14px; line-height: 1.9; color: #F2EFE9; }
658	
659	/* --- AWARDS --- */
660	.pn-awards { list-style: none; margin: 0; padding: 0; display: grid; }
661	.pn-awards__item { display: grid; grid-template-columns: 54px 1fr; gap: 14px; padding: 18px 0; border-top: 1px solid #23211D; align-items: baseline; }
662	.pn-awards__item:last-child { border-bottom: 1px solid #23211D; }
663	.pn-awards__year { font-family: "Cormorant Garamond", Georgia, serif; font-size: 17px; color: #C9A34E; }
664	.pn-awards__text { font-family: "Zen Old Mincho", serif; font-size: 13.5px; line-height: 1.95; color: #C6C1B7; }
665	.pn-awards__text em { font-style: normal; color: #F2EFE9; }
666	
667	/* --- PERFORMANCE --- */
668	.pn-videos { display: grid; gap: clamp(26px,4cqw,44px); }
669	.pn-video__frame { position: relative; aspect-ratio: 16/9; border: 1px solid #23211D; background: #0E0E10; }
670	.pn-video__frame iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }
671	.pn-video__cap { margin: 12px 0 0; display: flex; justify-content: space-between; gap: 14px; font-size: 12px; color: #8A8579; font-family: "Zen Old Mincho", serif; }
672	.pn-video__no { font-family: Archivo, sans-serif; font-size: 10px; letter-spacing: 0.2em; color: #C9A34E; }
673	
674	/* --- CONTACT / SNS --- */
675	.pn-contact__mail { display: inline-block; margin-top: 6px; font-family: "Cormorant Garamond", Georgia, serif; font-size: clamp(22px,5cqw,34px); letter-spacing: 0.03em; color: #E4C97E; border-bottom: 1px solid rgba(201,163,78,0.4); padding-bottom: 6px; }
676	.pn-sns { list-style: none; margin: clamp(34px,5cqw,52px) 0 0; padding: 0; display: grid; gap: 1px; background: #23211D; border: 1px solid #23211D; }
677	.pn-sns__link { display: flex; align-items: center; gap: 14px; background: #08080A; padding: 18px 20px; font-family: Archivo, sans-serif; font-size: 12px; letter-spacing: 0.18em; color: #F2EFE9; transition: background .35s ease, color .35s ease; }
678	.pn-sns__link:hover { background: #100E0A; color: #E4C97E; }
679	.pn-sns__icon { width: 16px; height: 16px; filter: brightness(0) invert(1); opacity: .8; }
680	.pn-sns__arrow { margin-left: auto; color: #6E6A61; }
